mapper.select:
select

from survey_user_clock
where re_info_id = #{reInfoId}

  and survey_user_id = #{surveyUserId,jdbcType=BIGINT}


 and FIND_IN_SET(survey_user_id,
  (SELECT GROUP_CONCAT(i.user_id) FROM survey_investigator i LEFT JOIN (SELECT id FROM survey_franchisee WHERE id = #{orgId}
  UNION
  SELECT id FROM survey_franchisee WHERE parent_id = #{orgId}) f ON i.org_id  = f.id
  WHERE f.id is not null))

order by clock_time desc

mapper.update:
UPDATE survey_user_clock c
LEFT JOIN (
SELECT id,re_id,survey_user_id,survey_org_id FROM survey_investigator_re_info WHERE DATE_FORMAT(down_time,'%Y-%m') = DATE_FORMAT(NOW(),'%Y-%m')
) r ON c.survey_user_id = r.survey_user_id  AND r.survey_org_id = c.survey_org_id
SET c.re_id = r.re_id,c.re_info_id = r.id
WHERE DATE_FORMAT(c.clock_time,'%Y-%m') = #{reDate};

mapper.select:
        SELECT aa.clockTime,COUNT(aa.recordCount) recordCount,COUNT(aa.caseCount) caseCount,IF(MAX(aa.d)>1.5,TRUE,FALSE) red FROM (
	        SELECT DATE_FORMAT(a.clock_time, '%Y-%m-%d') clockTime,a.id recordCount, b.id caseCount,r.cityin_driving_money/r.reference_money d
	        FROM  survey_user_clock  a
	        LEFT JOIN survey_clock_case b ON a.id=b.clock_id
	        LEFT JOIN survey_clock_re_info r ON a.id = r.clock_id
	        WHERE DATE_FORMAT(a.clock_time, '%Y-%m')=#{dateTime}
	        AND a.survey_user_id = #{userId}

                and a.survey_org_id = #{orgId}

	        GROUP BY a.id
	    )aa  GROUP BY DATE_FORMAT(aa.clockTime, '%Y-%m-%d')
